-- =====================================================================
-- App features: push delivery, chat notifications, evening nudge,
-- barcode foods, and the starter exercise and food libraries.
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. PUSH DELIVERY
-- Every new notification row is sent to the recipient's phones by the
-- send-push Edge Function. The function re-reads the row and sets
-- pushed_at, so a repeated or forged call can't send anything twice.
-- The project URL lives in Vault (secret 'project_url'); without it, or
-- without pg_net (local tests), notifications stay inbox-only.
-- ---------------------------------------------------------------------
do $$
begin
  if exists (select 1 from pg_available_extensions where name = 'pg_net') then
    create extension if not exists pg_net;
  end if;
end $$;

alter table notifications add column if not exists pushed_at timestamptz;

create or replace function private.push_notification()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_url text;
begin
  if not (select default_push from notification_types where key = new.type_key) then
    return new;
  end if;
  if to_regclass('vault.decrypted_secrets') is null
     or not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                    where n.nspname = 'net' and p.proname = 'http_post') then
    return new;
  end if;
  execute $q$select decrypted_secret from vault.decrypted_secrets where name = 'project_url'$q$ into v_url;
  if v_url is null then
    return new;
  end if;
  execute $q$select net.http_post(url := $1, body := $2)$q$
    using v_url || '/functions/v1/send-push', jsonb_build_object('notification_id', new.id);
  return new;
end $$;

create trigger push_notification after insert on notifications
  for each row execute function private.push_notification();

-- ---------------------------------------------------------------------
-- 2. CHAT: a new message notifies the other participant (push + unread).
-- The in-app inbox hides these; the chat shows them instead.
-- ---------------------------------------------------------------------
create or replace function private.on_message()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  c record;
begin
  select coach_id, trainee_id into c from conversations where id = new.conversation_id;
  perform private.notify(
    case when new.sender_id = c.coach_id then c.trainee_id else c.coach_id end,
    'chat_message',
    jsonb_build_object(
      'conversation_id', new.conversation_id,
      'sender_id', new.sender_id,
      'sender_name', (select full_name from profiles where id = new.sender_id),
      'preview', left(new.body, 120)));
  return new;
end $$;

create trigger on_message after insert on messages
  for each row execute function private.on_message();

-- ---------------------------------------------------------------------
-- 3. EVENING NUDGE: at 8 pm local time, trainees who logged nothing today
-- get one "nothing logged" notification.
-- ---------------------------------------------------------------------
create or replace function private.notify_no_data_today()
returns int language plpgsql security definer set search_path = public as $$
declare
  t record;
  n int := 0;
begin
  for t in
    select ur.user_id, private.local_today(ur.user_id) as today,
           extract(hour from now() at time zone p.timezone) as local_hour
    from user_roles ur
    join roles r on r.id = ur.role_id and r.key = 'trainee'
    join profiles p on p.id = ur.user_id
  loop
    continue when t.local_hour <> 20;
    continue when exists (select 1 from workout_sessions where trainee_id = t.user_id and session_date = t.today)
               or exists (select 1 from meal_logs where trainee_id = t.user_id and log_date = t.today)
               or exists (select 1 from notifications where recipient_id = t.user_id and type_key = 'no_data_today'
                          and created_at > now() - interval '20 hours');
    perform private.notify(t.user_id, 'no_data_today', jsonb_build_object('date', t.today));
    n := n + 1;
  end loop;
  return n;
end $$;

do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('no-data-today', '23 * * * *', 'select private.notify_no_data_today()');
  end if;
end $$;

-- ---------------------------------------------------------------------
-- 4. FOODS: coaches may also save packaged products found by barcode
-- (Open Food Facts, ODbL: shown with attribution in the app).
-- ---------------------------------------------------------------------
drop policy foods_add on foods;
create policy foods_add on foods for insert to authenticated
  with check (((select private.has_role('coach')) and source in ('custom', 'open_food_facts')
               and created_by = (select auth.uid()))
              or (select private.is_admin()));

